import React, { useState, useEffect, useRef } from 'react';
import { ChevronUp, ChevronDown, Check } from 'lucide-react';
import { cn } from '../../lib/utils';

export function TimeSpinner({ onConfirm, initialTimeStr }: { onConfirm: (timeStr: string) => void, initialTimeStr?: string }) {
    const parseInitial = (str?: string) => {
        let initH = 10;
        let initM = 0;
        let initP = 'AM';

        if (str) {
            const match = str.trim().match(/^(\d{1,2}):(\d{1,2})\s*(AM|PM)?$/i);
            if (match) {
                let parsedH = parseInt(match[1], 10);
                initM = parseInt(match[2], 10);
                if (match[3]) {
                    initP = match[3].toUpperCase();
                } else if (parsedH >= 12) {
                    initP = 'PM';
                } else {
                    initP = 'AM';
                }

                if (parsedH > 12) {
                    parsedH -= 12;
                }
                if (parsedH === 0) parsedH = 12;
                initH = parsedH;
            }
        }
        return { initH, initM, initP };
    };

    const initial = parseInitial(initialTimeStr);
    const [p, setP] = useState(initial.initP);
    const [hStr, setHStr] = useState(String(initial.initH).padStart(2, '0'));
    const [mStr, setMStr] = useState(String(initial.initM).padStart(2, '0'));

    const hourInputRef = useRef<HTMLInputElement>(null);
    const minInputRef = useRef<HTMLInputElement>(null);

    // Sync from external initialTimeStr changes
    useEffect(() => {
        if (initialTimeStr) {
            const parsed = parseInitial(initialTimeStr);
            setP(parsed.initP);
            setHStr(String(parsed.initH).padStart(2, '0'));
            setMStr(String(parsed.initM).padStart(2, '0'));
        }
    }, [initialTimeStr]);

    // Spinner buttons handlers
    const incrementHour = () => {
        let cur = parseInt(hStr, 10);
        if (isNaN(cur)) cur = 10;
        const next = cur === 12 ? 1 : cur + 1;
        setHStr(String(next).padStart(2, '0'));
    };

    const decrementHour = () => {
        let cur = parseInt(hStr, 10);
        if (isNaN(cur)) cur = 10;
        const next = cur === 1 ? 12 : cur - 1;
        setHStr(String(next).padStart(2, '0'));
    };

    const incrementMinute = () => {
        let cur = parseInt(mStr, 10);
        if (isNaN(cur)) cur = 0;
        const next = cur === 59 ? 0 : cur + 1;
        setMStr(String(next).padStart(2, '0'));
    };

    const decrementMinute = () => {
        let cur = parseInt(mStr, 10);
        if (isNaN(cur)) cur = 0;
        const next = cur === 0 ? 59 : cur - 1;
        setMStr(String(next).padStart(2, '0'));
    };

    // Direct input editing
    const handleHourChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        let val = e.target.value.replace(/[^0-9]/g, '');
        if (val.length > 2) val = val.slice(0, 2);
        setHStr(val);

        if (val.length > 0) {
            const num = parseInt(val, 10);
            if (!isNaN(num)) {
                if (num >= 13 && num <= 23) {
                    setP('PM');
                }
                if (val.length === 2 || num > 1) {
                    setTimeout(() => {
                        minInputRef.current?.focus();
                    }, 10);
                }
            }
        }
    };

    const handleHourBlur = () => {
        let num = parseInt(hStr, 10);
        if (isNaN(num) || num < 1) {
            num = 12;
        } else if (num > 12) {
            if (num <= 23) {
                num = num - 12;
                setP('PM');
            } else {
                num = 12;
            }
        }
        setHStr(String(num).padStart(2, '0'));
    };

    const handleMinuteChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        let val = e.target.value.replace(/[^0-9]/g, '');
        if (val.length > 2) val = val.slice(0, 2);
        setMStr(val);
    };

    const handleMinuteBlur = () => {
        let num = parseInt(mStr, 10);
        if (isNaN(num) || num < 0 || num > 59) {
            num = 0;
        }
        setMStr(String(num).padStart(2, '0'));
    };

    const handleConfirm = () => {
        let finalH = parseInt(hStr, 10);
        let finalM = parseInt(mStr, 10);
        let finalP = p;

        if (isNaN(finalH) || finalH < 1) finalH = 12;
        if (finalH > 12) {
            if (finalH <= 23) {
                finalH = finalH - 12;
                finalP = 'PM';
            } else {
                finalH = 12;
            }
        }
        if (finalH === 0) finalH = 12;

        if (isNaN(finalM) || finalM < 0 || finalM > 59) finalM = 0;

        const formatted = `${String(finalH).padStart(2, '0')}:${String(finalM).padStart(2, '0')} ${finalP}`;
        onConfirm(formatted);
    };

    const handleHourKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'ArrowUp') {
            e.preventDefault();
            incrementHour();
        } else if (e.key === 'ArrowDown') {
            e.preventDefault();
            decrementHour();
        } else if (e.key === 'Enter') {
            e.preventDefault();
            handleConfirm();
        }
    };

    const handleMinuteKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'ArrowUp') {
            e.preventDefault();
            incrementMinute();
        } else if (e.key === 'ArrowDown') {
            e.preventDefault();
            decrementMinute();
        } else if (e.key === 'Enter') {
            e.preventDefault();
            handleConfirm();
        }
    };

    const setQuickTime = (minutes: number) => {
        setMStr(String(minutes).padStart(2, '0'));
    };

    const setCurrentTime = () => {
        const now = new Date();
        let hours = now.getHours();
        const minutes = now.getMinutes();
        const period = hours >= 12 ? 'PM' : 'AM';
        if (hours > 12) hours -= 12;
        if (hours === 0) hours = 12;
        setHStr(String(hours).padStart(2, '0'));
        setMStr(String(minutes).padStart(2, '0'));
        setP(period);
    };

    return (
        <div className="flex flex-col gap-3.5 w-full select-none">
            {/* Time Selector Controls */}
            <div className="flex items-center justify-center gap-1.5 pt-1">
                {/* Hours Box & Controls */}
                <div className="flex flex-col items-center gap-0.5">
                    <button 
                        type="button" 
                        onClick={incrementHour} 
                        className="w-10 h-5 flex items-center justify-center rounded-md text-muted-foreground/60 hover:text-foreground hover:bg-muted/60 transition-colors cursor-pointer"
                        title="Increment hour"
                    >
                        <ChevronUp size={14} />
                    </button>

                    <input 
                        ref={hourInputRef}
                        type="text"
                        inputMode="numeric"
                        value={hStr}
                        onChange={handleHourChange}
                        onBlur={handleHourBlur}
                        onKeyDown={handleHourKeyDown}
                        className="w-13 h-11 text-center text-xl font-medium font-mono text-foreground bg-muted/40 border border-border/40 focus:border-primary/50 focus:bg-background rounded-xl p-0 m-0 tracking-tight transition-all"
                        style={{ outline: 'none', WebkitAppearance: 'none' }}
                    />

                    <button 
                        type="button" 
                        onClick={decrementHour} 
                        className="w-10 h-5 flex items-center justify-center rounded-md text-muted-foreground/60 hover:text-foreground hover:bg-muted/60 transition-colors cursor-pointer"
                        title="Decrement hour"
                    >
                        <ChevronDown size={14} />
                    </button>
                </div>

                {/* Center Colon Separator */}
                <div className="text-lg font-light text-muted-foreground/40 select-none pb-0.5 px-0.5">:</div>

                {/* Minutes Box & Controls */}
                <div className="flex flex-col items-center gap-0.5">
                    <button 
                        type="button" 
                        onClick={incrementMinute} 
                        className="w-10 h-5 flex items-center justify-center rounded-md text-muted-foreground/60 hover:text-foreground hover:bg-muted/60 transition-colors cursor-pointer"
                        title="Increment minute"
                    >
                        <ChevronUp size={14} />
                    </button>

                    <input 
                        ref={minInputRef}
                        type="text"
                        inputMode="numeric"
                        value={mStr}
                        onChange={handleMinuteChange}
                        onBlur={handleMinuteBlur}
                        onKeyDown={handleMinuteKeyDown}
                        className="w-13 h-11 text-center text-xl font-medium font-mono text-foreground bg-muted/40 border border-border/40 focus:border-primary/50 focus:bg-background rounded-xl p-0 m-0 tracking-tight transition-all"
                        style={{ outline: 'none', WebkitAppearance: 'none' }}
                    />

                    <button 
                        type="button" 
                        onClick={decrementMinute} 
                        className="w-10 h-5 flex items-center justify-center rounded-md text-muted-foreground/60 hover:text-foreground hover:bg-muted/60 transition-colors cursor-pointer"
                        title="Decrement minute"
                    >
                        <ChevronDown size={14} />
                    </button>
                </div>

                {/* AM / PM Segmented Control */}
                <div className="h-11 p-0.5 bg-muted/40 rounded-xl border border-border/40 self-center flex flex-col justify-between ml-1.5">
                    <button 
                        type="button"
                        onClick={() => setP('AM')}
                        className={cn(
                            "h-[18px] px-2 rounded-lg text-[10px] font-medium tracking-normal transition-all select-none flex items-center justify-center cursor-pointer",
                            p === 'AM' 
                                ? "bg-primary text-primary-foreground shadow-xs" 
                                : "text-muted-foreground/70 hover:text-foreground"
                        )}
                    >
                        AM
                    </button>
                    <button 
                        type="button"
                        onClick={() => setP('PM')}
                        className={cn(
                            "h-[18px] px-2 rounded-lg text-[10px] font-medium tracking-normal transition-all select-none flex items-center justify-center cursor-pointer",
                            p === 'PM' 
                                ? "bg-primary text-primary-foreground shadow-xs" 
                                : "text-muted-foreground/70 hover:text-foreground"
                        )}
                    >
                        PM
                    </button>
                </div>
            </div>

            {/* Quick Minute Presets */}
            <div className="flex items-center justify-center gap-1">
                <button
                    type="button"
                    onClick={setCurrentTime}
                    className="px-2.5 py-1 rounded-full text-[10px] font-medium bg-muted/50 hover:bg-muted text-muted-foreground hover:text-foreground transition-all cursor-pointer border border-border/40"
                >
                    Now
                </button>
                {[0, 15, 30, 45].map((m) => (
                    <button
                        key={m}
                        type="button"
                        onClick={() => setQuickTime(m)}
                        className={cn(
                            "px-2.5 py-1 rounded-full text-[10px] font-mono transition-all cursor-pointer border",
                            parseInt(mStr, 10) === m
                                ? "bg-primary/10 text-primary border-primary/30 font-medium"
                                : "bg-muted/50 hover:bg-muted text-muted-foreground/80 hover:text-foreground border-border/40 font-normal"
                        )}
                    >
                        :{String(m).padStart(2, '0')}
                    </button>
                ))}
            </div>

            {/* Confirm Time Button */}
            <button 
                type="button"
                onClick={handleConfirm}
                className="w-full bg-primary/90 hover:bg-primary text-primary-foreground rounded-xl h-8.5 font-medium text-xs tracking-normal shadow-xs active:scale-[0.99] transition-all flex items-center justify-center gap-1.5 cursor-pointer border-0 mt-0.5"
            >
                <Check size={13} className="opacity-80" />
                <span>Confirm</span>
            </button>
        </div>
    );
}
